export const packingScript = (u, j, h, a = {}, x = []) => `<script>
const searchInput = document.getElementById('orderSearch');
const results = document.getElementById('orderResults');
let debounce;
searchInput.addEventListener('input', function () {
  clearTimeout(debounce);
  const q = searchInput.value.trim();
  if (q.length < 2) { results.classList.add('d-none'); return; }
  debounce = setTimeout(function () {
    fetch('${h(u('api/orders_search.php'))}?q=' + encodeURIComponent(q))
      .then(r => r.json()).then(data => {
        results.innerHTML = '';
        (data.results || []).forEach(function (o) {
          const div = document.createElement('div');
          div.style.padding = '8px 12px'; div.style.cursor = 'pointer';
          div.textContent = (o.short_order_code || o.order_number) + ' — ' + o.customer_name + ' (' + o.mobile + ')';
          div.addEventListener('click', function () { window.location.href = '?order_id=' + o.id; });
          results.appendChild(div);
        });
        results.classList.toggle('d-none', (data.results || []).length === 0);
      });
  }, 300);
});
document.getElementById('selectAllPkg')?.addEventListener('click', function () {
  document.querySelectorAll('.pkg-check').forEach(cb => cb.checked = true);
});
document.getElementById('pkgPrintForm')?.addEventListener('submit', function (e) {
  if (document.querySelectorAll('.pkg-check:checked').length === 0) { e.preventDefault(); alert('Select at least one package.'); }
});
</script>`;
