export const scanScript = (u, j, h, a = {}, x = []) => `<script src="https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js"></script>
<script>
function doLookup(token) {
  if (!token) return;
  fetch('${h(u('api/qr_lookup.php'))}?token=' + encodeURIComponent(token))
    .then(r => r.json()).then(data => {
      document.getElementById('result').classList.add('d-none');
      document.getElementById('notFound').classList.add('d-none');
      if (!data.success) { document.getElementById('notFound').classList.remove('d-none'); return; }
      document.getElementById('rOrder').textContent = data.order_number;
      document.getElementById('rCustomer').textContent = data.customer_name + ' (' + data.customer_mobile + ')';
      document.getElementById('rGarment').textContent = data.garment_name + ' [' + data.sequence + ']';
      document.getElementById('rService').textContent = data.service_name;
      document.getElementById('rStatus').textContent = data.status;
      document.getElementById('rDue').textContent = data.due_date;
      document.getElementById('openOrderBtn').href = '${h(u('modules/orders/view.php'))}?id=' + data.order_id;
      document.getElementById('openGarmentBtn').href = '${h(u('modules/barcode/garment_detail.php'))}?item_id=' + data.order_item_id;
      document.getElementById('result').classList.remove('d-none');
    });
}
document.getElementById('lookupBtn').addEventListener('click', function () { doLookup(document.getElementById('tokenInput').value.trim()); });
${x[0]}

// ============================================================================
// CAMERA SCANNING — v6: jsQR, a completely independent pure-JS decoder.
//
// WHY: the native BarcodeDetector approach (v4/v5) was tested extensively on the real device —
// API present, secure context true, video genuinely flowing at up to 1080x1920/readyState=4,
// zero JS errors thrown — yet detect() returned zero matches across 600–1540 calls per attempt,
// repeated across multiple sessions even after fixing camera resolution. That combination
// (present API, healthy video, zero errors, zero results, unaffected by resolution) is the
// signature of the BROWSER'S OWN native barcode-detection backend being non-functional on this
// specific device — something no amount of JS-side tuning of BarcodeDetector calls could fix.
// jsQR replaces that native backend entirely: it decodes pixels drawn to a plain <canvas> using
// its own bundled algorithm, with zero dependency on BarcodeDetector or any OS/Play-Services
// component. If THIS also fails with zero matches, that is strong evidence the problem is with
// the captured image data itself (framing/focus/lighting) rather than any specific detector.
// ============================================================================
(function () {
  const startBtn = document.getElementById('startCameraBtn');
  const stopBtn = document.getElementById('stopCameraBtn');
  const video = document.getElementById('scanVideo');
  const scanFrame = document.getElementById('scanFrame');
  const canvas = document.getElementById('scanCanvas');
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  const statusMsg = document.getElementById('cameraStatusMsg');
  const diag = document.getElementById('cameraDiag');

  // v7 tuning constants (see the scanLoop comment for the measurements behind these).
  const TARGET_LONG_SIDE = 480;   // bounded analysis resolution
  const INVERT_EVERY_N = 5;       // inverted pass only every Nth decode, not twice every frame
  const CADENCE_MS = 80;          // controlled decode cadence instead of requestAnimationFrame

  let stream = null;
  let timerId = null;
  let attempts = 0;               // actual jsQR invocations
  let frames = 0;                 // loop ticks
  let decoding = false;           // in-flight guard — decodes never overlap
  let lastMs = 0;
  let lastResultLen = null;
  let lastBrightness = null;
  let lastError = null;
  let running = false;

  function stopCamera() {
    running = false;
    if (timerId) { clearTimeout(timerId); timerId = null; }
    if (stream) { stream.getTracks().forEach(function (t) { t.stop(); }); stream = null; }
    video.style.display = 'none';
    if (scanFrame) scanFrame.style.display = 'none';
    startBtn.classList.remove('d-none');
    stopBtn.classList.add('d-none');
  }

  // Mean brightness over a sparse pixel sample. This is the check v6's diagnostics were missing:
  // it proves real camera pixels actually reached the canvas. A blank/unpainted canvas reads ~0,
  // which would have proven drawImage was the failure instead. Never inspects or transmits image
  // content — one scalar only.
  function meanBrightness(data) {
    let sum = 0, n = 0;
    for (let i = 0; i < data.length; i += 4 * 97) {
      sum += (data[i] + data[i + 1] + data[i + 2]) / 3;
      n++;
    }
    return n ? Math.round(sum / n) : 0;
  }
  stopBtn.addEventListener('click', function () { stopCamera(); statusMsg.textContent = 'Camera stopped.'; });

  function updateDiag(extra) {
    diag.classList.remove('d-none');
    diag.textContent = [
      'isSecureContext: ' + window.isSecureContext,
      'typeof jsQR: ' + typeof jsQR,
      'video: ' + video.videoWidth + 'x' + video.videoHeight + ' readyState=' + video.readyState + ' paused=' + video.paused,
      'analysis canvas: ' + canvas.width + 'x' + canvas.height + '  (bounded to ' + TARGET_LONG_SIDE + 'px long side)',
      'loop ticks: ' + frames + '   jsQR decodes: ' + attempts,
      'decode duration: ' + lastMs + ' ms' + (lastMs > 0 ? '   (ceiling ~' + (1000 / lastMs).toFixed(1) + ' decodes/sec)' : ''),
      'pixel sanity — mean brightness 0-255: ' + (lastBrightness === null ? '-' : lastBrightness),
      'last decode result: ' + (lastResultLen === null ? 'none yet' : 'DECODED, payload length ' + lastResultLen),
      'last error: ' + (lastError || 'none'),
    ].join('\\n') + (extra ? '\\n' + extra : '');
  }

  // --- v7 FIX (decode pipeline). v6's decoder choice (jsQR) was CORRECT and is kept; v6 was
  // starving it. Measured with the exact deployed jsQR bundle on a fast x86 CPU:
  //   1080x1920 + attemptBoth  = 116 ms/frame   <-- what v6 did, every frame
  //   1080x1920 + dontInvert   =  44 ms/frame
  //    480x853  + attemptBoth  =  18 ms/frame
  // v6 also drove this from requestAnimationFrame, which throttles hard once the main thread is
  // saturated by a >100 ms synchronous decode. Device diagnostics corroborate: "attempts: 20"
  // in one session, "attempts: 0" in another (v6 refreshed that counter only every 10 attempts,
  // so 0 proves fewer than ten frames had completed). The decoder was fine — verified separately
  // by running this same bundle against a real UDC token QR outside the browser, where it decoded
  // at every QR size from 200-800 px inside a 1080x1920 frame.
  // Three changes: bound analysis resolution; dontInvert normally with an occasional inverted
  // pass; explicit cadence + in-flight guard so exactly one decode runs at a time.
  function scanLoop() {
    if (!running) return;
    frames++;
    if (!decoding && video.videoWidth > 0 && video.videoHeight > 0) {
      decoding = true;
      try {
        const vw = video.videoWidth, vh = video.videoHeight;
        const scale = Math.min(1, TARGET_LONG_SIDE / Math.max(vw, vh));
        const cw = Math.max(1, Math.round(vw * scale));
        const ch = Math.max(1, Math.round(vh * scale));
        if (canvas.width !== cw || canvas.height !== ch) { canvas.width = cw; canvas.height = ch; }
        ctx.drawImage(video, 0, 0, cw, ch);
        const imageData = ctx.getImageData(0, 0, cw, ch);
        lastBrightness = meanBrightness(imageData.data);

        // NOTE: 'onlyInvert' is BROKEN in jsQR 1.4.0 — verified by running this exact bundle
        // directly: it throws "Cannot read properties of undefined (reading 'height')". Using
        // 'attemptBoth' for the occasional fallback frame instead; it is safe, and because it
        // runs only every Nth frame it costs a fraction of what v6's every-frame attemptBoth did.
        const mode = (attempts % INVERT_EVERY_N === 0) ? 'attemptBoth' : 'dontInvert';
        const t0 = performance.now();
        const code = jsQR(imageData.data, cw, ch, { inversionAttempts: mode });
        lastMs = Math.round(performance.now() - t0);
        attempts++;
        lastError = null;

        if (code && code.data) {
          lastResultLen = code.data.length;
          // Payload LENGTH only — the secure token itself is never written to the diagnostics.
          updateDiag('MATCH FOUND (payload length ' + code.data.length + ') — looking up…');
          statusMsg.textContent = 'QR code found!';
          stopCamera();
          decoding = false;
          try {
            const url = new URL(code.data);
            const token = url.searchParams.get('token') || code.data;
            document.getElementById('tokenInput').value = token;
            doLookup(token);
          } catch (e) {
            document.getElementById('tokenInput').value = code.data;
            doLookup(code.data);
          }
          return;
        }
      } catch (err) {
        lastError = (err && err.message) ? err.message : String(err);
      }
      decoding = false;
    }
    if (frames % 5 === 0) updateDiag();
    timerId = setTimeout(scanLoop, CADENCE_MS);
  }

  startBtn.addEventListener('click', async function () {
    if (typeof jsQR === 'undefined') {
      diag.classList.remove('d-none');
      diag.textContent = 'typeof jsQR: undefined\\nThe scanning library failed to load — please use manual entry.';
      statusMsg.textContent = 'Camera scanning is not available right now — please use manual entry below.';
      return;
    }
    attempts = 0; frames = 0; lastMs = 0; lastResultLen = null; lastBrightness = null; lastError = null;
    statusMsg.textContent = 'Requesting camera…';
    try {
      // Moderate capture size. Analysis is bounded independently above, but a smaller capture
      // also reduces drawImage cost and gives autofocus an easier target.
      stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } }
      });
    } catch (err) {
      statusMsg.textContent = '';
      diag.classList.remove('d-none');
      diag.textContent = 'getUserMedia() rejected: ' + (err && err.message ? err.message : err);
      alert('Could not access camera — please use manual entry instead.');
      return;
    }
    video.srcObject = stream;
    video.style.display = '';
    if (scanFrame) scanFrame.style.display = '';
    await video.play();
    startBtn.classList.add('d-none');
    stopBtn.classList.remove('d-none');
    statusMsg.textContent = 'Camera on — hold the tag steady inside the box.';
    running = true;
    updateDiag();
    scanLoop();
  });
})();
</script>`;
